window.CFA_LESSONS=(window.CFA_LESSONS||[]).concat([{"module_id":"CFA26-09-05","title":"The Behavioral Biases of Individuals","version":"2026","source_basis":[{"source_id":"CFAI_2026","pdf_pages":[213,248],"relation":"primary"},{"source_id":"Kaplan_2026","pdf_pages":[130,143],"relation":"supplementary"},{"source_id":"SAPP_2026","pdf_pages":[162,212],"relation":"supplementary"}],"los_coverage":[{"los_id":"CFA26-09-05-LOS01","learning_goal_vi":"So sánh và phân biệt cognitive errors với emotional biases.","status":"targeted_CFAI_Kaplan_SAPP_and_independent_math_QA_pass","competency_criteria":["Theo LOS CFA Institute Curriculum 2026","Đối chiếu Kaplan và SAPP theo nguồn","Giải thích concepts, tình huống và các phương án sai","Kiểm tra các phép tính và test website"],"concept_ids":["S01-01","S01-02","S01-03","S01-04","S01-05"],"formula_ids":["F01-01"],"example_ids":["E01-01","E01-02"],"question_ids":["Q01-01","Q01-02","Q01-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":215},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":130},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":162}},"missing_items":[]},{"los_id":"CFA26-09-05-LOS02","learning_goal_vi":"Thảo luận những behavioral biases được nhận diện phổ biến và tác động đến quyết định tài chính.","status":"targeted_CFAI_Kaplan_SAPP_and_independent_math_QA_pass","competency_criteria":["Theo LOS CFA Institute Curriculum 2026","Đối chiếu Kaplan và SAPP theo nguồn","Giải thích concepts, tình huống và các phương án sai","Kiểm tra các phép tính và test website"],"concept_ids":["S02-01","S02-02","S02-03","S02-04","S02-05","S02-06"],"formula_ids":["F02-01"],"example_ids":["E02-01","E02-02"],"question_ids":["Q02-01","Q02-02","Q02-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":224},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":131},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":164}},"missing_items":[]},{"los_id":"CFA26-09-05-LOS03","learning_goal_vi":"Mô tả behavioral biases có thể tạo ra những đặc điểm thị trường ngoài giải thích của traditional finance.","status":"targeted_CFAI_Kaplan_SAPP_and_independent_math_QA_pass","competency_criteria":["Theo LOS CFA Institute Curriculum 2026","Đối chiếu Kaplan và SAPP theo nguồn","Giải thích concepts, tình huống và các phương án sai","Kiểm tra các phép tính và test website"],"concept_ids":["S03-01","S03-02","S03-03","S03-04","S03-05"],"formula_ids":["F03-01"],"example_ids":["E03-01","E03-02"],"question_ids":["Q03-01","Q03-02","Q03-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":238},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":138},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":203}},"missing_items":[]}],"sections":[{"id":"S01-01","los_ids":["CFA26-09-05-LOS01"],"heading_vi":"Cognitive errors là lỗi xử lý thông tin","body_vi":"Cognitive biases xuất phát từ niềm tin và cách thu thập, diễn giải hoặc xử lý thông tin không hợp lý. Có hai nhóm: belief perseverance (khó sửa niềm tin trước dữ liệu mới) và information-processing errors (cách đánh giá thông tin sai). Giáo dục, checklists, phản biện giả định và quy trình định lượng có thể giúp giảm nhiều lỗi nhận thức."},{"id":"S01-02","los_ids":["CFA26-09-05-LOS01"],"heading_vi":"Emotional biases là phản ứng tâm lý","body_vi":"Emotional biases xuất phát từ cảm xúc, cảm giác mất mát, tự tin quá mức và sự thoải mái khi không thay đổi quyết định. Chúng khó sửa chỉ bằng cung cấp dữ liệu; một số trường hợp cần điều chỉnh portfolio và kỳ vọng cho phù hợp behavior của client."},{"id":"S01-03","los_ids":["CFA26-09-05-LOS01"],"heading_vi":"Các lỗi belief perseverance","body_vi":"Conservatism, confirmation, representativeness, illusion of control và hindsight thường khiến analyst duy trì hoặc diễn giải beliefs sai. Ví dụ confirmation bias là ưu tiên đọc báo cáo ủng hộ một cổ phiếu và loại bỏ bằng chứng phản bác."},{"id":"S01-04","los_ids":["CFA26-09-05-LOS01"],"heading_vi":"Information-processing errors","body_vi":"Anchoring, mental accounting, framing và availability làm méo decision vì điểm neo, ngăn tài khoản nhân tạo, cách đóng khung câu hỏi và thông tin dễ nhớ. Cùng xác suất khách quan có thể bị chọn khác chỉ vì mô tả dưới dạng gain hay loss."},{"id":"S01-05","los_ids":["CFA26-09-05-LOS01"],"heading_vi":"Không nhầm nhóm với hậu quả","body_vi":"Cognitive và emotional đều có thể gây turnover sai, under-diversification và lệch IPS; phân loại cần nhận diện nguyên nhân psychological/cognitive chứ không chỉ kết quả bán/mua."},{"id":"S02-01","los_ids":["CFA26-09-05-LOS02"],"heading_vi":"Confirmation, conservatism và representativeness","body_vi":"Confirmation khiến investor tìm nguồn hợp thesis và né nguồn trái chiều; conservatism làm cập nhật beliefs quá chậm; representativeness dự báo từ mẫu gần đây hoặc khuôn mẫu không đủ thống kê, bỏ qua base rates."},{"id":"S02-02","los_ids":["CFA26-09-05-LOS02"],"heading_vi":"Illusion of control và hindsight","body_vi":"Illusion of control gán khả năng kiểm soát kết quả ngẫu nhiên cho kỹ năng; hindsight khiến người ta tin sau sự kiện rằng kết quả đã luôn rõ ràng. Giải pháp là ghi forecast trước sự kiện cùng alternative scenarios để đánh giá trung thực."},{"id":"S02-03","los_ids":["CFA26-09-05-LOS02"],"heading_vi":"Anchoring, mental accounting, framing và availability","body_vi":"Anchoring quá phụ thuộc giá mua/forecast; mental accounting đánh giá danh mục theo các tài khoản riêng làm sai tối ưu toàn danh mục; framing thay đổi lựa chọn theo ngôn từ; availability coi sự kiện gần đây dễ nhớ là phổ biến hơn xác suất thực."},{"id":"S02-04","los_ids":["CFA26-09-05-LOS02"],"heading_vi":"Loss aversion và disposition effect","body_vi":"Loss-averse investor ngại hiện thực lỗ, có thể bán winners quá sớm và giữ losers quá lâu. Giá vốn không phải thông tin đầy đủ về intrinsic value; cần đánh giá thesis mới, thuế và risk budget thay vì sunk cost."},{"id":"S02-05","los_ids":["CFA26-09-05-LOS02"],"heading_vi":"Overconfidence, self-control và status quo","body_vi":"Overconfidence làm overtrading, đòn bẩy/under-diversification; self-control bias khiến tiêu dùng hiện tại quá lớn, không tiết kiệm đủ; status quo và endowment khiến nắm giữ tài sản quen thuộc ngay cả khi portfolio lệch IPS. Regret aversion khiến né quyết định khi sợ hối hận."},{"id":"S02-06","los_ids":["CFA26-09-05-LOS02"],"heading_vi":"Khắc phục và lựa chọn accommodation","body_vi":"Sử dụng checklists, investment diary, pre-mortem, định kỳ rebalance và diversification; với emotional bias khó thay đổi, điều chỉnh asset mix để client có thể kiên trì giữ strategy thay vì đưa ra allocation lý thuyết quá rủi ro."},{"id":"S03-01","los_ids":["CFA26-09-05-LOS03"],"heading_vi":"Từ hành vi cá nhân đến giá thị trường","body_vi":"Nếu đủ nhiều nhà đầu tư cùng chịu bias, demand/supply và risk-taking có thể tạo price pressure không hoàn toàn phản ánh fundamentals. Arbitrageurs đối mặt funding limits, short-selling constraints và timing risk, nên mispricing có thể tồn tại lâu."},{"id":"S03-02","los_ids":["CFA26-09-05-LOS03"],"heading_vi":"Underreaction, overreaction và momentum","body_vi":"Conservatism có thể làm phản ứng quá chậm với thông tin mới, tạo post-event drift hoặc short-term momentum; representativeness/availability có thể khiến kỳ vọng bị extrapolate quá mức rồi đảo chiều. Không dùng mô hình đơn lẻ giải thích mọi anomaly."},{"id":"S03-03","los_ids":["CFA26-09-05-LOS03"],"heading_vi":"Bubbles và herd behavior","body_vi":"Herding, overconfidence, illusion of control và fear of missing out có thể khuếch đại bubbles khi giá tăng làm nhà đầu tư tin giá sẽ tiếp tục tăng. Bubble khó xác định trong thời gian thực vì intrinsic value không quan sát trực tiếp."},{"id":"S03-04","los_ids":["CFA26-09-05-LOS03"],"heading_vi":"Home bias và disposition","body_vi":"Investors thường ưu tiên chứng khoán trong nước/quanh nơi quen thuộc dù diversification quốc tế có thể hữu ích; disposition effect có thể làm supply pressure theo điểm lời/lỗ khi market moves."},{"id":"S03-05","los_ids":["CFA26-09-05-LOS03"],"heading_vi":"Phân biệt anomalies với bằng chứng chắc chắn","body_vi":"Momentum, size/value patterns, calendar effects hoặc excessive volatility có thể chịu data mining, changing risk premia, transaction costs và sample selection. Không nên tuyên bố arbitrage phi rủi ro chỉ vì tìm thấy một historical anomaly."}],"formulae":[{"id":"F01-01","los_ids":["CFA26-09-05-LOS01"],"expression":"Decision gap = Realized behavior outcome − Rational benchmark outcome","variables":["Only a descriptive comparison for analysis, not a universal CFA quantitative model."],"assumptions":["Behavioral effects are contextual and often hard to identify causally."]},{"id":"F02-01","los_ids":["CFA26-09-05-LOS02"],"expression":"Disposition ratio = Winners sold / Total winners held","variables":["Illustrative behavior metric, not CFA standardized ratio."],"assumptions":["Used only as qualitative illustration when analyzing trading behavior."]},{"id":"F03-01","los_ids":["CFA26-09-05-LOS03"],"expression":"Abnormal return = Realized return − Model-implied expected return","variables":["Depends on benchmark model and horizon."],"assumptions":["Abnormal returns can reflect model mismeasurement or risk factors, not guaranteed arbitrage."]}],"worked_examples":[{"id":"E01-01","los_ids":["CFA26-09-05-LOS01"],"problem":"Nhà phân tích giữ price target100 dù công ty công bố earnings thấp hơn forecast đáng kể.","solution_steps":["Điểm neo price target ban đầu làm revision không đủ dù có thông tin mới.","Đây là anchoring/adjustment bias thuộc cognitive errors."],"answer":"Cần re-estimate cash flows và discount rates từ thông tin cập nhật thay vì bám giá mục tiêu 100."},{"id":"E01-02","los_ids":["CFA26-09-05-LOS01"],"problem":"Investor lỗ 30% liên tục kiểm tra giá, không chịu bán cổ phiếu vì đau đớn khi hiện thực lỗ.","solution_steps":["Loss aversion tạo asymmetry between losses and gains.","Phản ứng xuất phát cảm xúc mất mát hơn là sai công thức thống kê."],"answer":"Loss aversion thuộc emotional bias, cần khung IPS và risk tolerance phù hợp."},{"id":"E02-01","los_ids":["CFA26-09-05-LOS02"],"problem":"Investor mua stock giá100, giá xuống60, thông tin fundamental xấu đi nhưng giữ chỉ vì chưa về vốn.","solution_steps":["Giá mua 100 không làm expected future return cao hơn; đây là anchoring/loss aversion.","Đánh giá sell/hold bằng NPV của dòng tiền mới và portfolio risks, không dùng breakeven psychology."],"answer":"Cần cập nhật thesis độc lập với purchase cost, cân nhắc bán nếu không còn phù hợp."},{"id":"E02-02","los_ids":["CFA26-09-05-LOS02"],"problem":"Manager giao dịch 200 lần/năm vì tin có thể dự báo biến động từng ngày, sau phí underperform benchmark.","solution_steps":["Hành vi có thể đến từ overconfidence và illusion of control.","So sánh realized net return, turnover và benchmark, đồng thời ghi forecast ex ante."],"answer":"Giảm turnover thiếu cơ sở và kiểm định năng lực dự báo trên dữ liệu ngoài mẫu."},{"id":"E03-01","los_ids":["CFA26-09-05-LOS03"],"problem":"Cổ phiếu phản ứng ít ngày đầu sau tin lợi nhuận dương, tăng dần trong vài tuần.","solution_steps":["Underreaction có thể phù hợp belief conservatism và adjustment chậm.","Không bảo đảm alpha vì chi phí giao dịch/risk có thể bù đắp anomaly."],"answer":"Có thể là post-announcement drift; cần kiểm nghiệm thống kê và giao dịch thực tế."},{"id":"E03-02","los_ids":["CFA26-09-05-LOS03"],"problem":"Investors tập trung cổ phiếu quê nhà, portfolio thiếu exposure quốc tế.","solution_steps":["Home bias có thể do familiarity và comfort, dù foreign assets có thể giảm covariance.","Cần xem currency, taxes và legal constraints trước khi khẳng định exposure quốc tế tốt hơn."],"answer":"Home bias có thể dẫn tới concentration risk nhưng không phải mọi home allocation đều phi lý."}],"questions":[{"id":"Q01-01","los_ids":["CFA26-09-05-LOS01"],"stem":"Anchoring và adjustment bias được phân loại?","options":["Emotional bias","Systematic market risk","Cognitive information-processing"],"correct_option":2,"explanation":"Anchoring khiến investor cập nhật chưa đủ từ điểm neo ban đầu, là lỗi xử lý thông tin thay vì phản ứng cảm xúc thuần."},{"id":"Q01-02","los_ids":["CFA26-09-05-LOS01"],"stem":"Loss aversion thuộc?","options":["Emotional bias","Accounting policy","Belief perseverance"],"correct_option":0,"explanation":"Loss aversion phản ánh cảm xúc khi mất tiền lớn hơn sự hài lòng với cùng mức được; thường gây disposition effect."},{"id":"Q01-03","los_ids":["CFA26-09-05-LOS01"],"stem":"Mệnh đề nào đúng nhất?","options":["Emotional bias luôn dễ sửa bằng training","Cognitive bias đôi khi có thể giảm bằng checklist và học hỏi","Cognitive bias luôn không thể sửa"],"correct_option":1,"explanation":"Bằng chứng và quy trình giúp khắc phục nhiều lỗi nhận thức; emotional biases thường cần accommodation nhiều hơn."},{"id":"Q02-01","los_ids":["CFA26-09-05-LOS02"],"stem":"Investor chỉ đọc nghiên cứu ủng hộ cổ phiếu sẵn có, đây là?","options":["Sharpe ratio","Market beta","Confirmation bias"],"correct_option":2,"explanation":"Confirmation là xu hướng chỉ tìm bằng chứng xác nhận belief hiện tại và bỏ qua dữ liệu phủ định, nên phân tích dễ sai."},{"id":"Q02-02","los_ids":["CFA26-09-05-LOS02"],"stem":"Giữ lỗ, bán lãi quá sớm thường liên quan?","options":["Loss aversion / disposition effect","Duration convexity","Term structure"],"correct_option":0,"explanation":"Loss aversion và disposition effect khiến thắng bị hiện thực sớm, thua được giữ lâu vì đau đớn ghi nhận lỗ."},{"id":"Q02-03","los_ids":["CFA26-09-05-LOS02"],"stem":"Manager liên tục mua bán vì quá tin vào dự đoán cá nhân có thể mắc?","options":["Maturity mismatch","Overconfidence bias","Self-control duy nhất"],"correct_option":1,"explanation":"Overconfidence gây đánh giá quá cao chất lượng thông tin và kỹ năng, tạo giao dịch nhiều với costs lớn."},{"id":"Q03-01","los_ids":["CFA26-09-05-LOS03"],"stem":"Price momentum có thể liên quan đến?","options":["Luôn thị trường hiệu quả mạnh","Rủi ro default bằng 0","Underreaction do belief updating chậm"],"correct_option":2,"explanation":"Một lời giải behavioral cho momentum là thông tin được phản ánh chậm; vẫn tồn tại cách giải thích bằng risk premia."},{"id":"Q03-02","los_ids":["CFA26-09-05-LOS03"],"stem":"Herding trong bubble có thể dẫn tới?","options":["Giá lệch xa fundamentals","Mọi tài sản có correlation−1","Loại bỏ volatility"],"correct_option":0,"explanation":"Đám đông cùng mua theo kỳ vọng sẽ có người mua giá cao hơn có thể làm giá lệch fundamental value kéo dài."},{"id":"Q03-03","los_ids":["CFA26-09-05-LOS03"],"stem":"Anomaly lịch sử có chắc mang lại arbitrage phi rủi ro?","options":["Chỉ nếu Sharpe cao","Không, do costs, limits to arbitrage và model uncertainty","Chắc chắn"],"correct_option":1,"explanation":"Tín hiệu quá khứ có thể không tồn tại ngoài mẫu hoặc bị transaction costs, short constraints và rủi ro triệt tiêu."}],"flashcards":[{"id":"C01-01","los_ids":["CFA26-09-05-LOS01"],"front":"Cognitive errors là lỗi xử lý thông tin — giải thích và cách xử lý?","back":"Cognitive biases xuất phát từ niềm tin và cách thu thập, diễn giải hoặc xử lý thông tin không hợp lý. Có hai nhóm: belief perseverance (khó sửa niềm tin trước dữ liệu mới) và information-processing errors (cách đánh giá thông tin sai). Giáo dục, checklists, phản biện giả định và quy trình định lượng có thể giúp giảm nhiều lỗi nhận thức."},{"id":"C01-02","los_ids":["CFA26-09-05-LOS01"],"front":"Emotional biases là phản ứng tâm lý — giải thích và cách xử lý?","back":"Emotional biases xuất phát từ cảm xúc, cảm giác mất mát, tự tin quá mức và sự thoải mái khi không thay đổi quyết định. Chúng khó sửa chỉ bằng cung cấp dữ liệu; một số trường hợp cần điều chỉnh portfolio và kỳ vọng cho phù hợp behavior của client."},{"id":"C01-03","los_ids":["CFA26-09-05-LOS01"],"front":"Các lỗi belief perseverance — giải thích và cách xử lý?","back":"Conservatism, confirmation, representativeness, illusion of control và hindsight thường khiến analyst duy trì hoặc diễn giải beliefs sai. Ví dụ confirmation bias là ưu tiên đọc báo cáo ủng hộ một cổ phiếu và loại bỏ bằng chứng phản bác."},{"id":"C02-01","los_ids":["CFA26-09-05-LOS02"],"front":"Confirmation, conservatism và representativeness — giải thích và cách xử lý?","back":"Confirmation khiến investor tìm nguồn hợp thesis và né nguồn trái chiều; conservatism làm cập nhật beliefs quá chậm; representativeness dự báo từ mẫu gần đây hoặc khuôn mẫu không đủ thống kê, bỏ qua base rates."},{"id":"C02-02","los_ids":["CFA26-09-05-LOS02"],"front":"Illusion of control và hindsight — giải thích và cách xử lý?","back":"Illusion of control gán khả năng kiểm soát kết quả ngẫu nhiên cho kỹ năng; hindsight khiến người ta tin sau sự kiện rằng kết quả đã luôn rõ ràng. Giải pháp là ghi forecast trước sự kiện cùng alternative scenarios để đánh giá trung thực."},{"id":"C02-03","los_ids":["CFA26-09-05-LOS02"],"front":"Anchoring, mental accounting, framing và availability — giải thích và cách xử lý?","back":"Anchoring quá phụ thuộc giá mua/forecast; mental accounting đánh giá danh mục theo các tài khoản riêng làm sai tối ưu toàn danh mục; framing thay đổi lựa chọn theo ngôn từ; availability coi sự kiện gần đây dễ nhớ là phổ biến hơn xác suất thực."},{"id":"C03-01","los_ids":["CFA26-09-05-LOS03"],"front":"Từ hành vi cá nhân đến giá thị trường — giải thích và cách xử lý?","back":"Nếu đủ nhiều nhà đầu tư cùng chịu bias, demand/supply và risk-taking có thể tạo price pressure không hoàn toàn phản ánh fundamentals. Arbitrageurs đối mặt funding limits, short-selling constraints và timing risk, nên mispricing có thể tồn tại lâu."},{"id":"C03-02","los_ids":["CFA26-09-05-LOS03"],"front":"Underreaction, overreaction và momentum — giải thích và cách xử lý?","back":"Conservatism có thể làm phản ứng quá chậm với thông tin mới, tạo post-event drift hoặc short-term momentum; representativeness/availability có thể khiến kỳ vọng bị extrapolate quá mức rồi đảo chiều. Không dùng mô hình đơn lẻ giải thích mọi anomaly."},{"id":"C03-03","los_ids":["CFA26-09-05-LOS03"],"front":"Bubbles và herd behavior — giải thích và cách xử lý?","back":"Herding, overconfidence, illusion of control và fear of missing out có thể khuếch đại bubbles khi giá tăng làm nhà đầu tư tin giá sẽ tiếp tục tăng. Bubble khó xác định trong thời gian thực vì intrinsic value không quan sát trực tiếp."}],"review_status":"targeted_los_source_math_and_browser_QA_pass_not_exhaustive_all_PDFs"},{"module_id":"CFA26-09-06","title":"Introduction to Risk Management","version":"2026","source_basis":[{"source_id":"CFAI_2026","pdf_pages":[249,300],"relation":"primary"},{"source_id":"Kaplan_2026","pdf_pages":[144,153],"relation":"supplementary"},{"source_id":"SAPP_2026","pdf_pages":[213,241],"relation":"supplementary"}],"los_coverage":[{"los_id":"CFA26-09-06-LOS01","learning_goal_vi":"Định nghĩa risk management.","status":"targeted_CFAI_Kaplan_SAPP_and_independent_math_QA_pass","competency_criteria":["Theo LOS CFA Institute Curriculum 2026","Đối chiếu Kaplan và SAPP theo nguồn","Giải thích concepts, tình huống và các phương án sai","Kiểm tra các phép tính và test website"],"concept_ids":["S01-01","S01-02","S01-03","S01-04"],"formula_ids":["F01-01"],"example_ids":["E01-01","E01-02"],"question_ids":["Q01-01","Q01-02","Q01-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":251},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":144},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":213}},"missing_items":[]},{"los_id":"CFA26-09-06-LOS02","learning_goal_vi":"Mô tả các đặc điểm của risk management framework.","status":"targeted_CFAI_Kaplan_SAPP_and_independent_math_QA_pass","competency_criteria":["Theo LOS CFA Institute Curriculum 2026","Đối chiếu Kaplan và SAPP theo nguồn","Giải thích concepts, tình huống và các phương án sai","Kiểm tra các phép tính và test website"],"concept_ids":["S02-01","S02-02","S02-03","S02-04","S02-05"],"formula_ids":["F02-01"],"example_ids":["E02-01","E02-02"],"question_ids":["Q02-01","Q02-02","Q02-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":254},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":144},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":214}},"missing_items":[]},{"los_id":"CFA26-09-06-LOS03","learning_goal_vi":"Định nghĩa risk governance và mô tả yếu tố cấu thành governance hiệu quả.","status":"targeted_CFAI_Kaplan_SAPP_and_independent_math_QA_pass","competency_criteria":["Theo LOS CFA Institute Curriculum 2026","Đối chiếu Kaplan và SAPP theo nguồn","Giải thích concepts, tình huống và các phương án sai","Kiểm tra các phép tính và test website"],"concept_ids":["S03-01","S03-02","S03-03","S03-04","S03-05"],"formula_ids":["F03-01"],"example_ids":["E03-01","E03-02"],"question_ids":["Q03-01","Q03-02","Q03-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":260},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":145},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":219}},"missing_items":[]},{"los_id":"CFA26-09-06-LOS04","learning_goal_vi":"Giải thích risk tolerance tác động tới risk management.","status":"targeted_CFAI_Kaplan_SAPP_and_independent_math_QA_pass","competency_criteria":["Theo LOS CFA Institute Curriculum 2026","Đối chiếu Kaplan và SAPP theo nguồn","Giải thích concepts, tình huống và các phương án sai","Kiểm tra các phép tính và test website"],"concept_ids":["S04-01","S04-02","S04-03","S04-04"],"formula_ids":["F04-01"],"example_ids":["E04-01","E04-02"],"question_ids":["Q04-01","Q04-02","Q04-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":263},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":145},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":221}},"missing_items":[]},{"los_id":"CFA26-09-06-LOS05","learning_goal_vi":"Mô tả risk budgeting và vai trò trong risk governance.","status":"targeted_CFAI_Kaplan_SAPP_and_independent_math_QA_pass","competency_criteria":["Theo LOS CFA Institute Curriculum 2026","Đối chiếu Kaplan và SAPP theo nguồn","Giải thích concepts, tình huống và các phương án sai","Kiểm tra các phép tính và test website"],"concept_ids":["S05-01","S05-02","S05-03","S05-04","S05-05"],"formula_ids":["F05-01","F05-02"],"example_ids":["E05-01","E05-02"],"question_ids":["Q05-01","Q05-02","Q05-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":266},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":145},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":222}},"missing_items":[]},{"los_id":"CFA26-09-06-LOS06","learning_goal_vi":"Nhận diện financial và non-financial risks và cách chúng tương tác.","status":"targeted_CFAI_Kaplan_SAPP_and_independent_math_QA_pass","competency_criteria":["Theo LOS CFA Institute Curriculum 2026","Đối chiếu Kaplan và SAPP theo nguồn","Giải thích concepts, tình huống và các phương án sai","Kiểm tra các phép tính và test website"],"concept_ids":["S06-01","S06-02","S06-03","S06-04","S06-05"],"formula_ids":["F06-01","F06-02"],"example_ids":["E06-01","E06-02"],"question_ids":["Q06-01","Q06-02","Q06-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":273},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":146},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":225}},"missing_items":[]},{"los_id":"CFA26-09-06-LOS07","learning_goal_vi":"Mô tả phương pháp đo và điều chỉnh risk exposures cùng yếu tố lựa chọn phương pháp.","status":"targeted_CFAI_Kaplan_SAPP_and_independent_math_QA_pass","competency_criteria":["Theo LOS CFA Institute Curriculum 2026","Đối chiếu Kaplan và SAPP theo nguồn","Giải thích concepts, tình huống và các phương án sai","Kiểm tra các phép tính và test website"],"concept_ids":["S07-01","S07-02","S07-03","S07-04","S07-05","S07-06"],"formula_ids":["F07-01","F07-02","F07-03"],"example_ids":["E07-01","E07-02"],"question_ids":["Q07-01","Q07-02","Q07-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V9_PortMgt_ONLINE.pdf","pdf_page":280},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":147},"SAPP_2026":{"file":"SAPP Portfolio Management.pdf","pdf_page":232}},"missing_items":[]}],"sections":[{"id":"S01-01","los_ids":["CFA26-09-06-LOS01"],"heading_vi":"Risk management là lựa chọn có ý thức","body_vi":"Risk management là quá trình xác định risk exposures, đo lường/giám sát và điều chỉnh các rủi ro phù hợp với mục tiêu, khả năng chịu rủi ro và constraints. Mục đích không phải loại bỏ tất cả risk: tổ chức tạo lợi nhuận bằng cách nhận những rủi ro có bù đắp hợp lý."},{"id":"S01-02","los_ids":["CFA26-09-06-LOS01"],"heading_vi":"Risk và uncertainty","body_vi":"Risk có thể ước lượng distribution hoặc xác suất tổn thất; uncertainty bao gồm thiếu hiểu biết về distribution và kịch bản. Risk management cần chuẩn bị cho cả known unknowns và khó đo lường như cyber events hoặc regulatory shifts."},{"id":"S01-03","los_ids":["CFA26-09-06-LOS01"],"heading_vi":"Risk-bearing capacity và enterprise value","body_vi":"Nhận quá nhiều rủi ro có thể làm mất solvency hoặc thanh khoản, nhưng phòng hộ mọi biến động có thể tốn chi phí và bỏ lỡ risk premium. Tối ưu risk/return là lựa chọn có tính chiến lược chứ không phải cắt volatility về 0."},{"id":"S01-04","los_ids":["CFA26-09-06-LOS01"],"heading_vi":"Quy trình liên tục và nhiều lớp","body_vi":"Rủi ro phát sinh từ hoạt động và môi trường, không chỉ financial markets; quản lý rủi ro cần cập nhật exposures theo thời gian, đặt limits, phản hồi incidents và truyền thông trách nhiệm giữa business lines và governance."},{"id":"S02-01","los_ids":["CFA26-09-06-LOS02"],"heading_vi":"Chính sách, quy trình và nhân sự","body_vi":"Risk management framework chỉ rõ risk appetite, policies, responsibilities, reporting, systems và escalation protocols. Các bước thiết yếu gồm identify, measure/assess, manage, monitor/report và review/revise."},{"id":"S02-02","los_ids":["CFA26-09-06-LOS02"],"heading_vi":"Mục tiêu liên kết chiến lược","body_vi":"Risk management phải gắn strategic objectives, asset-liability profile và capital/liquidity availability. Một chỉ tiêu VaR duy nhất không thể thay thế kiểm tra credit, operational, liquidity và business risk."},{"id":"S02-03","los_ids":["CFA26-09-06-LOS02"],"heading_vi":"Risk metrics và limits","body_vi":"Thiết lập risk indicators, exposure limits, stress tests và capital allocations; báo cáo cần nêu breach, concentration, trends và quality of models. Nếu thresholds không có hành động khi vi phạm thì framework chỉ là hình thức."},{"id":"S02-04","los_ids":["CFA26-09-06-LOS02"],"heading_vi":"Governance và independence","body_vi":"Board và senior management định chiến lược/tolerance, business units chịu trách nhiệm rủi ro hoạt động; independent risk function kiểm soát và thách thức giả định, internal audit đánh giá governance. Responsibilities phải tách biệt phù hợp quy mô."},{"id":"S02-05","los_ids":["CFA26-09-06-LOS02"],"heading_vi":"Chuyển từ phản ứng sang chủ động","body_vi":"Framework tốt phát hiện rủi ro trước khủng hoảng, tổ chức diễn tập và thay đổi exposures; không chỉ lập báo cáo sau khi đã mất tiền. Nâng cấp theo thị trường, technology và regulations thay đổi."},{"id":"S03-01","los_ids":["CFA26-09-06-LOS03"],"heading_vi":"Risk governance là oversight","body_vi":"Risk governance xác định ai đặt risk appetite, phê duyệt policies, giám sát exposures và chịu trách nhiệm accountability. Hội đồng quản trị hoặc cơ quan tương đương đặt các giới hạn tổng thể, trong khi management chuyển hóa thành thực thi."},{"id":"S03-02","los_ids":["CFA26-09-06-LOS03"],"heading_vi":"Board, risk committee và risk officers","body_vi":"Board ban hành chiến lược/tolerance, risk committee giám sát concentration, CRO/risk management báo cáo độc lập, business lines nhận và quản lý rủi ro tạo ra; internal audit kiểm tra thiết kế và tuân thủ controls."},{"id":"S03-03","los_ids":["CFA26-09-06-LOS03"],"heading_vi":"Culture và incentives","body_vi":"Effective governance đòi hỏi minh bạch, ethical tone at top, incentives không khuyến khích giấu tail risk để đạt bonus ngắn hạn, escalation rõ ràng khi vượt limit và dữ liệu rủi ro đáng tin cậy."},{"id":"S03-04","los_ids":["CFA26-09-06-LOS03"],"heading_vi":"Risk reporting và board oversight","body_vi":"Thông tin phải kịp thời, đủ chi tiết về market/credit/operational/liquidity risks, stress scenarios và limits. Board không cần xử lý từng giao dịch nhưng phải đủ năng lực thách thức model assumptions và risk concentrations."},{"id":"S03-05","los_ids":["CFA26-09-06-LOS03"],"heading_vi":"Governance và enterprise risk management","body_vi":"ERM xem rủi ro của toàn doanh nghiệp, kể cả tương tác giữa units; không đơn giản cộng từng VaR độc lập nếu có correlation hoặc contagion. Governance dùng capital/liquidity capacity làm giới hạn cho quyết định kinh doanh."},{"id":"S04-01","los_ids":["CFA26-09-06-LOS04"],"heading_vi":"Risk tolerance là mức chấp nhận biến động/mất mát","body_vi":"Risk tolerance chỉ mức biến động hoặc tổn thất tổ chức cho phép so mục tiêu, khác risk capacity là maximum risk có thể chịu mà không mất khả năng tồn tại. Tolerance phải cụ thể hóa thành limits cho units và các asset classes."},{"id":"S04-02","los_ids":["CFA26-09-06-LOS04"],"heading_vi":"Liên kết strategic objectives","body_vi":"Growth company có thể chọn tolerance cho business/technology risk cao hơn pension fund phải trả liabilities gần; không có một con số VaR tối ưu cho mọi tổ chức. Risk tolerance ảnh hưởng risk budget và lựa chọn hedging."},{"id":"S04-03","los_ids":["CFA26-09-06-LOS04"],"heading_vi":"Mục tiêu so với stress","body_vi":"Đặt limits cho leverage, liquidity, concentration, expected shortfall và credit exposure; tổ chức nên stress test xem tolerance có còn phù hợp với worst plausible scenarios hay không."},{"id":"S04-04","los_ids":["CFA26-09-06-LOS04"],"heading_vi":"Tính động và governance","body_vi":"Risk tolerance cần xem khi capital, revenues, funding hoặc regulations thay đổi, nhưng không thể tự ý nới chỉ vì vừa thua lỗ. Quá trình thay đổi phải được governing body thông qua và truyền đạt tới người thực thi."},{"id":"S05-01","los_ids":["CFA26-09-06-LOS05"],"heading_vi":"Risk budgeting phân bổ giới hạn","body_vi":"Risk budgeting chia overall risk capacity/tolerance thành budgets cho units, asset classes hoặc investment strategies để các bộ phận cạnh tranh quyền sử dụng scarce risk capital; phải tính interaction và correlation giữa exposures."},{"id":"S05-02","los_ids":["CFA26-09-06-LOS05"],"heading_vi":"Risk budget không phải capital budget","body_vi":"Capital budget phân bổ tiền; risk budget phân bổ một đơn vị rủi ro như VaR, expected shortfall, tracking error hoặc risk contribution. Hai chiến lược dùng cùng số tiền có thể tiêu thụ risk budget khác nhiều."},{"id":"S05-03","los_ids":["CFA26-09-06-LOS05"],"heading_vi":"Marginal và component risk","body_vi":"Risk contribution nên đo tác động của vị thế tới portfolio total risk, không chỉ stand-alone σ. Portfolio concentration và correlations có thể khiến việc cộng các individual risks không bằng overall risk."},{"id":"S05-04","los_ids":["CFA26-09-06-LOS05"],"heading_vi":"Theo dõi và tái phân bổ","body_vi":"Khi active strategies thay đổi factor exposures, risk manager cần cập nhật budget utilization, limits và challenge incentive alignment. Không tự động tăng risk budget khi strategy thua lỗ chỉ để gỡ lại."},{"id":"S05-05","los_ids":["CFA26-09-06-LOS05"],"heading_vi":"Risk budgeting và performance evaluation","body_vi":"So excess return tạo ra với capital/risk consumed giúp đánh giá chiến lược hiệu quả; units có Sharpe/Information Ratio cao có thể nhận risk budget khác nhưng phải xét model uncertainty và liquidity."},{"id":"S06-01","los_ids":["CFA26-09-06-LOS06"],"heading_vi":"Financial risks","body_vi":"Market risk gồm equity, interest rate, FX, commodity price; credit risk gồm counterparty default, migration và spread changes; liquidity risk gồm market liquidity và funding liquidity. Các exposure tương tác khi giá tài sản giảm và margin requirements tăng."},{"id":"S06-02","los_ids":["CFA26-09-06-LOS06"],"heading_vi":"Non-financial risks","body_vi":"Operational errors, cyberattacks, fraud, model risk, legal/regulatory, reputational, environmental, geopolitical và strategic risks. Chúng có thể tác động tài chính lớn, không nên coi rủi ro phi tài chính là không thể lượng hóa hoặc không quan trọng."},{"id":"S06-03","los_ids":["CFA26-09-06-LOS06"],"heading_vi":"Interaction qua chuỗi nguyên nhân","body_vi":"Cyber breach làm hoạt động dừng, khách hàng rút tiền, funding liquidity thắt chặt, credit rating xấu và interest costs tăng. Cú sốc tỷ giá có thể làm khách vay ngoại tệ khó trả nợ, gây credit loss."},{"id":"S06-04","los_ids":["CFA26-09-06-LOS06"],"heading_vi":"Wrong-way risk và concentration","body_vi":"Rủi ro counterparty có thể tăng đúng khi exposure tăng, ví dụ derivative gain cho bank trùng lúc counterparty mất solvency. Risk aggregation đơn giản bỏ qua wrong-way risk và contagion thường đánh giá thấp stress loss."},{"id":"S06-05","los_ids":["CFA26-09-06-LOS06"],"heading_vi":"Phát hiện rủi ro có liên hệ","body_vi":"Risk register kết hợp scenario analysis, network dependencies, stress testing và early-warning indicators; cần phối hợp financial/operational/compliance để xử lý nguồn nguyên nhân thay vì đo rủi ro riêng lẻ."},{"id":"S07-01","los_ids":["CFA26-09-06-LOS07"],"heading_vi":"Risk measurement: sensitivity, volatility, VaR, ES","body_vi":"Sensitivity measures gồm duration, beta, delta, DV01; volatility mô tả biến động; VaR ước tính loss threshold ở confidence/horizon nhất định; Expected Shortfall đo kỳ vọng tổn thất trong tail vượt VaR. Không coi VaR là maximum possible loss."},{"id":"S07-02","los_ids":["CFA26-09-06-LOS07"],"heading_vi":"VaR models và assumptions","body_vi":"Parametric VaR giả định distribution, historical VaR dựa phân phối lịch sử, Monte Carlo mô phỏng scenarios theo model. Những phương pháp có model risk, sensitivity to sample, liquidity horizon và tail risk; cần backtesting/stress testing."},{"id":"S07-03","los_ids":["CFA26-09-06-LOS07"],"heading_vi":"Stress testing và scenario analysis","body_vi":"Stress test kiểm tra losses dưới cú sốc extreme nhưng hợp lý; scenario analysis kết hợp yield/FX/equity/credit events. Các thước đo này bổ sung chứ không thay thế VaR/ES. Stress phải xét correlated adverse moves và loss of liquidity."},{"id":"S07-04","los_ids":["CFA26-09-06-LOS07"],"heading_vi":"Risk modification","body_vi":"Phương án include avoidance (không vào vị thế), reduction (giảm notional/leverage), diversification, hedging bằng futures/options/swaps, insurance, risk transfer, setting limits và accepting risk khi reward đủ. Hedging có basis/counterparty/liquidity costs."},{"id":"S07-05","los_ids":["CFA26-09-06-LOS07"],"heading_vi":"Lựa chọn công cụ","body_vi":"Xét effectiveness, cost, availability, legal authority, execution complexity, model/counterparty risks và treatment trong IPS. Ví dụ futures hedge interest risk hiệu quả nhưng có margin calls cần cash buffer."},{"id":"S07-06","los_ids":["CFA26-09-06-LOS07"],"heading_vi":"Thước đo phù hợp loại rủi ro","body_vi":"DV01/duration cho fixed-income small rate shifts; option delta/gamma cho nonlinear payoffs; VaR/ES cho tổng distributions nhưng cần complement liquidity, cyber, default, governance scenarios. Thước đo đơn lẻ hiếm khi đủ."}],"formulae":[{"id":"F01-01","los_ids":["CFA26-09-06-LOS01"],"expression":"Risk-adjusted objective = Expected reward − cost of bearing/mitigating risk","variables":["Conceptual representation, not fixed CFA formula."],"assumptions":["Must assess risk tolerance, capital, and liquidity constraints."]},{"id":"F02-01","los_ids":["CFA26-09-06-LOS02"],"expression":"Risk exposure utilization = Current exposure / Risk limit","variables":["Same currency and measurement period."],"assumptions":["Limit set by governing body; not universal CFA ratio."]},{"id":"F03-01","los_ids":["CFA26-09-06-LOS03"],"expression":"Total enterprise exposure ≠ Sum of isolated worst cases in general","variables":["Correlations, common factors and nonlinear contagion matter."],"assumptions":["Conceptual warning; no fixed universal aggregation rule."]},{"id":"F04-01","los_ids":["CFA26-09-06-LOS04"],"expression":"Exposure headroom=Risk tolerance limit−Measured exposure","variables":["Exposure and limit in same units."],"assumptions":["Simplified measure; nonlinear exposures require scenario analysis."]},{"id":"F05-01","los_ids":["CFA26-09-06-LOS05"],"expression":"Budget utilization_i=Measured risk_i / Allocated risk budget_i","variables":["Common risk metric and horizon."],"assumptions":["Independent risks may not aggregate linearly."]},{"id":"F05-02","los_ids":["CFA26-09-06-LOS05"],"expression":"Risk contribution_i≈w_i ∂σp/∂w_i","variables":["Portfolio σ differentiable; same risk metric."],"assumptions":["Euler-style risk decomposition under homogeneous volatility models."]},{"id":"F06-01","los_ids":["CFA26-09-06-LOS06"],"expression":"Expected credit loss ≈ PD×LGD×EAD","variables":["Simplified single-period measure for credit risk."],"assumptions":["Does not include funding liquidity/counterparty wrong-way risk."]},{"id":"F06-02","los_ids":["CFA26-09-06-LOS06"],"expression":"FX transaction exposure ≈ Net foreign-currency position × FX rate change","variables":["Linear approximation for short horizon."],"assumptions":["Hedges, taxes, nonlinearity may modify actual P&L."]},{"id":"F07-01","los_ids":["CFA26-09-06-LOS07"],"expression":"Parametric VaR ≈ z×σportfolio×MV","variables":["Simplified zero-mean Normal one-period assumption."],"assumptions":["VaR is loss quantile, not worst loss; mean shift may matter."]},{"id":"F07-02","los_ids":["CFA26-09-06-LOS07"],"expression":"Expected Shortfall = E[Loss | Loss ≥ VaR threshold]","variables":["Tail average loss beyond specified confidence."],"assumptions":["Needs full loss distribution and convention for quantile ties."]},{"id":"F07-03","los_ids":["CFA26-09-06-LOS07"],"expression":"DV01≈Modified duration × Bond MV × 0.0001","variables":["Price sensitivity for small parallel yield changes."],"assumptions":["Linear approximation, ignores convexity and credit spread changes."]}],"worked_examples":[{"id":"E01-01","los_ids":["CFA26-09-06-LOS01"],"problem":"Tổ chức có hoạt động xuất khẩu thu USD, phải trả nguyên liệu bằng EUR.","solution_steps":["Xác định hai exposure tiền tệ, đánh giá net exposure thay vì hedge từng hóa đơn biệt lập.","Lựa chọn hedge một phần phù hợp risk budget, không nhất thiết loại bỏ toàn bộ FX risk."],"answer":"Risk management cần nhận diện, đo lường và quyết định phần risk chấp nhận hay phòng hộ."},{"id":"E01-02","los_ids":["CFA26-09-06-LOS01"],"problem":"Quỹ nắm 70% cổ phiếu tăng trưởng có expected return cao nhưng risk of ruin lớn.","solution_steps":["Xem portfolio concentration, correlations, liquidity và drawdown scenarios.","Có thể giảm exposure, đa dạng hóa hoặc tăng cash buffer tùy IPS; không tối đa expected return bằng mọi giá."],"answer":"Quản lý rủi ro chủ động đánh đổi reward, risk và survival."},{"id":"E02-01","los_ids":["CFA26-09-06-LOS02"],"problem":"Risk limit exposure100 triệu, actual exposure85 triệu. Utilization?","solution_steps":["85/100=85%, headroom15 triệu.","Headroom có thể thay đổi nếu correlations hoặc risk factors xấu đi."],"answer":"Exposure utilization 85% trước adjustment stress."},{"id":"E02-02","los_ids":["CFA26-09-06-LOS02"],"problem":"Portfolio duration limit 5 năm, actual duration 6 năm.","solution_steps":["Limit breach1 năm, phải báo escalations theo framework.","Có thể hedging futures/swaps, rebalance fixed income hoặc cập nhật limit qua governance nếu justified."],"answer":"Breach cần hành động và ghi nhận, không chỉ theo dõi thụ động."},{"id":"E03-01","los_ids":["CFA26-09-06-LOS03"],"problem":"Trading desk lãi lớn nhưng lặp lại vượt VaR limit, risk officer không được phép báo board.","solution_steps":["Thiếu độc lập/escalation và governance yếu; bonus có thể khuyến khích risk-taking quá mức.","Board cần reporting quyền hạn và xử lý limit breaches."],"answer":"Cần cơ chế giám sát độc lập và accountability rõ ràng."},{"id":"E03-02","los_ids":["CFA26-09-06-LOS03"],"problem":"Board chấp nhận annual loss budget20 triệu nhưng business lines tự mở exposure dự kiến lỗ50 triệu.","solution_steps":["Management nên phát hiện aggregate exposure vượt tolerance.","Escalate và giảm risk hoặc điều chỉnh appetite qua quy trình board phê duyệt."],"answer":"Governance phải liên kết quyết định business với risk tolerance đã được phê duyệt."},{"id":"E04-01","los_ids":["CFA26-09-06-LOS04"],"problem":"Tổ chức chấp nhận maximum expected loss6 triệu, model đo exposure5 triệu.","solution_steps":["Headroom=6−5=1 triệu theo metric đang dùng.","Không được hiểu là còn chắc chắn không thua vượt 6 triệu; model có assumptions/tails."],"answer":"Còn headroom danh nghĩa1 triệu, cần stress testing bổ sung."},{"id":"E04-02","los_ids":["CFA26-09-06-LOS04"],"problem":"Tài sản quỹ hưu trí giảm, funding ratio xuống dưới ngưỡng chính sách.","solution_steps":["Risk capacity thay đổi khi funded status xấu.","Risk governance có thể giảm leverage hoặc duration mismatch, đồng thời review risk tolerance qua proper approvals."],"answer":"Không tự động tăng risk-taking để “gỡ lỗ” nếu không còn capacity."},{"id":"E05-01","los_ids":["CFA26-09-06-LOS05"],"problem":"Risk budget VaR20 triệu, strategy A đã dùng VaR15 triệu; utilization?","solution_steps":["Utilization=15/20=75%.","Remaining headroom5 triệu nếu metric tính nhất quán."],"answer":"Budget utilization75%, không phải 15%."},{"id":"E05-02","los_ids":["CFA26-09-06-LOS05"],"problem":"Hai strategies có vốn đầu tư bằng nhau 50 triệu, σA=5%, σB=20%.","solution_steps":["Stand-alone risk contribution có thể rất khác dù vốn bằng nhau.","Phải tính correlations để biết marginal risk của mỗi strategy với toàn portfolio."],"answer":"Không chia risk budget chỉ bằng nominal capital invested."},{"id":"E06-01","los_ids":["CFA26-09-06-LOS06"],"problem":"Counterparty PD4%, LGD50%, EAD10 triệu; expected loss?","solution_steps":["EL=0,04×0,50×10=0,20 triệu.","Nếu exposure tăng cùng lúc PD tăng vì wrong-way risk, ước tính đơn giản có thể quá thấp."],"answer":"Expected loss khoảng200.000 theo giả định constant exposures."},{"id":"E06-02","los_ids":["CFA26-09-06-LOS06"],"problem":"Bank giữ asset marketable100 triệu; giá giảm20%, depositors rút30 triệu.","solution_steps":["Mark-to-market loss20 triệu làm assets giảm và khách hàng rút tiền tạo funding liquidity need30 triệu.","Nếu phải fire-sell nhiều hơn, market price giảm thêm: rủi ro thị trường và liquidity khuếch đại nhau."],"answer":"Sự kiện phối hợp market và liquidity risks, không thể phân tích tách rời hoàn toàn."},{"id":"E07-01","los_ids":["CFA26-09-06-LOS07"],"problem":"Portfolio value10 triệu, daily σ2%, z≈1,645. One-day 95% parametric VaR?","solution_steps":["VaR≈1,645×0,02×10 triệu=0,329 triệu.","Nếu Normality/linear assumptions sai, actual tail loss có thể lớn hơn."],"answer":"One-day 95% parametric VaR khoảng329.000; không phải maximum loss."},{"id":"E07-02","los_ids":["CFA26-09-06-LOS07"],"problem":"Bond MV20 triệu, modified duration5. DV01?","solution_steps":["DV01≈5×20 triệu×0,0001=10.000 mỗi 1bp.","Lãi suất tăng 10bp làm bond price giảm khoảng100.000 trước convexity và các factors khác."],"answer":"DV01 ≈10.000/1bp, local linear estimate."}],"questions":[{"id":"Q01-01","los_ids":["CFA26-09-06-LOS01"],"stem":"Risk management hướng tới điều gì?","options":["Chọn và kiểm soát risk exposures phù hợp mục tiêu/tolerance","Chỉ mua government bonds","Loại bỏ toàn bộ rủi ro dù mất lợi nhuận"],"correct_option":0,"explanation":"Risk management xác định, đo, giám sát và điều chỉnh risks, không mặc định xóa bỏ mọi nguồn risk premium."},{"id":"Q01-02","los_ids":["CFA26-09-06-LOS01"],"stem":"Risk appetite và risk capacity khác nhau vì?","options":["Capacity chỉ đo market volatility","Appetite là mức sẵn sàng nhận, capacity là mức có thể chịu","Hai khái niệm luôn giống nhau"],"correct_option":1,"explanation":"Tổ chức có thể muốn nhận risk nhiều hơn nguồn vốn chịu được; governance phải giữ exposure trong capacity."},{"id":"Q01-03","los_ids":["CFA26-09-06-LOS01"],"stem":"Một sự kiện cyber disruption được xem là?","options":["Risk-free opportunity","Chỉ market beta","Non-financial risk cần quản lý"],"correct_option":2,"explanation":"Operational/cyber risk là rủi ro phi tài chính trực tiếp nhưng có thể gây cash-flow, credit và reputation losses."},{"id":"Q02-01","los_ids":["CFA26-09-06-LOS02"],"stem":"Framework đầy đủ cần?","options":["Governance, identification, measurement, monitoring và response","Chỉ một Excel VaR","Chỉ legal compliance"],"correct_option":0,"explanation":"Risk management framework bao gồm policy, people, measurement, controls, review và communication chứ không chỉ metric."},{"id":"Q02-02","los_ids":["CFA26-09-06-LOS02"],"stem":"Current risk exposure85, limit100; utilization?","options":["117,6%","85%","15%"],"correct_option":1,"explanation":"Utilization=85/100=85%; remaining headroom 15 cùng đơn vị exposure."},{"id":"Q02-03","los_ids":["CFA26-09-06-LOS02"],"stem":"Limit breach trong quản lý rủi ro nên?","options":["Tự chỉnh báo cáo thành compliant","Bỏ qua nếu expected return cao","Escalate và xử lý theo policy"],"correct_option":2,"explanation":"Risk limit mất tác dụng nếu breach không được báo cáo, phân tích và xử lý theo governance."},{"id":"Q03-01","los_ids":["CFA26-09-06-LOS03"],"stem":"Ai thường chịu trách nhiệm đặt overall risk appetite?","options":["Board/governing body","Mỗi trader đơn lẻ","Nhà cung cấp dữ liệu"],"correct_option":0,"explanation":"Board hoặc governing body đặt mức tolerance tổng thể; business units triển khai trong giới hạn."},{"id":"Q03-02","los_ids":["CFA26-09-06-LOS03"],"stem":"CRO cần đặc tính nào?","options":["Luôn ký duyệt sales quota","Độc lập và có quyền escalation","Chỉ báo cáo khi có lãi"],"correct_option":1,"explanation":"Independent risk oversight và quyền báo cáo phù hợp bảo đảm risk limits có hiệu lực."},{"id":"Q03-03","los_ids":["CFA26-09-06-LOS03"],"stem":"Risk governance không hiệu quả khi?","options":["Limit được báo cáo minh bạch","Incentives tính tới risk-adjusted return","Bonus thưởng turnover bất kể risk và breach bị giấu"],"correct_option":2,"explanation":"Incentives lệch và thiếu escalation có thể tích lũy tail risks không được kiểm soát."},{"id":"Q04-01","los_ids":["CFA26-09-06-LOS04"],"stem":"Risk tolerance nên thể hiện thành?","options":["Risk limits và policies có thể đo/giám sát","Chỉ return mục tiêu","Cảm nhận mỗi trader"],"correct_option":0,"explanation":"Tolerance cần trở thành hạn mức exposure, drawdown, VaR/stress v.v. có thể quản trị."},{"id":"Q04-02","los_ids":["CFA26-09-06-LOS04"],"stem":"Limit6 triệu, measured5 triệu, headroom?","options":["30 triệu","1 triệu","11 triệu"],"correct_option":1,"explanation":"Headroom tính bằng tolerance limit trừ exposure cùng thước đo =1 triệu."},{"id":"Q04-03","los_ids":["CFA26-09-06-LOS04"],"stem":"Risk tolerance so với capacity có thể?","options":["Luôn lớn hơn mà không sao","Không liên quan solvency","Phải phù hợp capacity thực tế và objectives"],"correct_option":2,"explanation":"Risk tolerance không nên vượt khả năng hấp thụ tổn thất, kể cả khi ban lãnh đạo muốn sinh lợi cao."},{"id":"Q05-01","los_ids":["CFA26-09-06-LOS05"],"stem":"Risk budgeting phân bổ chủ yếu?","options":["Đơn vị rủi ro được cho phép","Chỉ số lượng nhân viên","Chỉ công nợ kế toán"],"correct_option":0,"explanation":"Risk budget phân bổ risk allowances theo metric có ý nghĩa, khác cash capital budget."},{"id":"Q05-02","los_ids":["CFA26-09-06-LOS05"],"stem":"VaR risk budget20, sử dụng15; utilization?","options":["133,3%","75%","25%"],"correct_option":1,"explanation":"15/20=75%, remaining nominal risk budget5; vẫn cần đánh giá model assumptions."},{"id":"Q05-03","los_ids":["CFA26-09-06-LOS05"],"stem":"Thêm asset có covariance âm với portfolio có thể?","options":["Luôn tăng risk contribution","Không đổi","Giảm marginal portfolio risk dù asset có stand-alone volatility"],"correct_option":2,"explanation":"Risk contribution phụ thuộc covariance với danh mục; stand-alone σ không quyết định toàn bộ."},{"id":"Q06-01","los_ids":["CFA26-09-06-LOS06"],"stem":"Cyberattack là ví dụ?","options":["Non-financial operational risk","Risk-free volatility","Chỉ systematic equity beta"],"correct_option":0,"explanation":"Cyber disruption thuộc operational risk; có thể chuyển thành direct financial loss, liquidity pressure và legal/reputational risks."},{"id":"Q06-02","los_ids":["CFA26-09-06-LOS06"],"stem":"Risk funding-liquidity có thể bị khuếch đại bởi?","options":["Tất cả khách hàng trả nợ sớm","Margin calls khi market prices giảm","Portfolio luôn profit"],"correct_option":1,"explanation":"Market shock tạo margin calls và haircut tăng, gây nhu cầu cash đột ngột ngay khi tài sản khó bán."},{"id":"Q06-03","los_ids":["CFA26-09-06-LOS06"],"stem":"PD4%, LGD50%, EAD10 triệu; EL?","options":["2 triệu","0,02 triệu","0,20 triệu"],"correct_option":2,"explanation":"Expected credit loss ≈0,04×0,5×10=0,20 triệu; wrong-way risks cần phân tích thêm ngoài công thức đơn giản."},{"id":"Q07-01","los_ids":["CFA26-09-06-LOS07"],"stem":"VaR 95% một ngày bằng 0,5 triệu nghĩa là?","options":["Khoảng 5% trường hợp có thể mất vượt 0,5 triệu trong mô hình","Không có tail risk","Maximum loss chắc chắn là 0,5 triệu"],"correct_option":0,"explanation":"VaR chỉ xác định quantile của loss distribution, không giới hạn severity của losses nằm ngoài quantile."},{"id":"Q07-02","los_ids":["CFA26-09-06-LOS07"],"stem":"Expected Shortfall so với VaR giúp?","options":["Chỉ tính lãi suất phi rủi ro","Đo trung bình losses ở vùng tail vượt threshold","Loại bỏ mọi model risk"],"correct_option":1,"explanation":"ES phản ánh tail severity, giúp bổ sung thông tin VaR không cho biết losses vượt ngưỡng sẽ sâu đến đâu."},{"id":"Q07-03","los_ids":["CFA26-09-06-LOS07"],"stem":"Bond MV20 triệu, mod duration5; DV01?","options":["100.000","1.000","10.000"],"correct_option":2,"explanation":"DV01≈Dmod×MV×0,0001=5×20.000.000×0,0001=10.000 đơn vị tiền cho 1bp."}],"flashcards":[{"id":"C01-01","los_ids":["CFA26-09-06-LOS01"],"front":"Risk management là lựa chọn có ý thức — giải thích và cách xử lý?","back":"Risk management là quá trình xác định risk exposures, đo lường/giám sát và điều chỉnh các rủi ro phù hợp với mục tiêu, khả năng chịu rủi ro và constraints. Mục đích không phải loại bỏ tất cả risk: tổ chức tạo lợi nhuận bằng cách nhận những rủi ro có bù đắp hợp lý."},{"id":"C01-02","los_ids":["CFA26-09-06-LOS01"],"front":"Risk và uncertainty — giải thích và cách xử lý?","back":"Risk có thể ước lượng distribution hoặc xác suất tổn thất; uncertainty bao gồm thiếu hiểu biết về distribution và kịch bản. Risk management cần chuẩn bị cho cả known unknowns và khó đo lường như cyber events hoặc regulatory shifts."},{"id":"C01-03","los_ids":["CFA26-09-06-LOS01"],"front":"Risk-bearing capacity và enterprise value — giải thích và cách xử lý?","back":"Nhận quá nhiều rủi ro có thể làm mất solvency hoặc thanh khoản, nhưng phòng hộ mọi biến động có thể tốn chi phí và bỏ lỡ risk premium. Tối ưu risk/return là lựa chọn có tính chiến lược chứ không phải cắt volatility về 0."},{"id":"C02-01","los_ids":["CFA26-09-06-LOS02"],"front":"Chính sách, quy trình và nhân sự — giải thích và cách xử lý?","back":"Risk management framework chỉ rõ risk appetite, policies, responsibilities, reporting, systems và escalation protocols. Các bước thiết yếu gồm identify, measure/assess, manage, monitor/report và review/revise."},{"id":"C02-02","los_ids":["CFA26-09-06-LOS02"],"front":"Mục tiêu liên kết chiến lược — giải thích và cách xử lý?","back":"Risk management phải gắn strategic objectives, asset-liability profile và capital/liquidity availability. Một chỉ tiêu VaR duy nhất không thể thay thế kiểm tra credit, operational, liquidity và business risk."},{"id":"C02-03","los_ids":["CFA26-09-06-LOS02"],"front":"Risk metrics và limits — giải thích và cách xử lý?","back":"Thiết lập risk indicators, exposure limits, stress tests và capital allocations; báo cáo cần nêu breach, concentration, trends và quality of models. Nếu thresholds không có hành động khi vi phạm thì framework chỉ là hình thức."},{"id":"C03-01","los_ids":["CFA26-09-06-LOS03"],"front":"Risk governance là oversight — giải thích và cách xử lý?","back":"Risk governance xác định ai đặt risk appetite, phê duyệt policies, giám sát exposures và chịu trách nhiệm accountability. Hội đồng quản trị hoặc cơ quan tương đương đặt các giới hạn tổng thể, trong khi management chuyển hóa thành thực thi."},{"id":"C03-02","los_ids":["CFA26-09-06-LOS03"],"front":"Board, risk committee và risk officers — giải thích và cách xử lý?","back":"Board ban hành chiến lược/tolerance, risk committee giám sát concentration, CRO/risk management báo cáo độc lập, business lines nhận và quản lý rủi ro tạo ra; internal audit kiểm tra thiết kế và tuân thủ controls."},{"id":"C03-03","los_ids":["CFA26-09-06-LOS03"],"front":"Culture và incentives — giải thích và cách xử lý?","back":"Effective governance đòi hỏi minh bạch, ethical tone at top, incentives không khuyến khích giấu tail risk để đạt bonus ngắn hạn, escalation rõ ràng khi vượt limit và dữ liệu rủi ro đáng tin cậy."},{"id":"C04-01","los_ids":["CFA26-09-06-LOS04"],"front":"Risk tolerance là mức chấp nhận biến động/mất mát — giải thích và cách xử lý?","back":"Risk tolerance chỉ mức biến động hoặc tổn thất tổ chức cho phép so mục tiêu, khác risk capacity là maximum risk có thể chịu mà không mất khả năng tồn tại. Tolerance phải cụ thể hóa thành limits cho units và các asset classes."},{"id":"C04-02","los_ids":["CFA26-09-06-LOS04"],"front":"Liên kết strategic objectives — giải thích và cách xử lý?","back":"Growth company có thể chọn tolerance cho business/technology risk cao hơn pension fund phải trả liabilities gần; không có một con số VaR tối ưu cho mọi tổ chức. Risk tolerance ảnh hưởng risk budget và lựa chọn hedging."},{"id":"C04-03","los_ids":["CFA26-09-06-LOS04"],"front":"Mục tiêu so với stress — giải thích và cách xử lý?","back":"Đặt limits cho leverage, liquidity, concentration, expected shortfall và credit exposure; tổ chức nên stress test xem tolerance có còn phù hợp với worst plausible scenarios hay không."},{"id":"C05-01","los_ids":["CFA26-09-06-LOS05"],"front":"Risk budgeting phân bổ giới hạn — giải thích và cách xử lý?","back":"Risk budgeting chia overall risk capacity/tolerance thành budgets cho units, asset classes hoặc investment strategies để các bộ phận cạnh tranh quyền sử dụng scarce risk capital; phải tính interaction và correlation giữa exposures."},{"id":"C05-02","los_ids":["CFA26-09-06-LOS05"],"front":"Risk budget không phải capital budget — giải thích và cách xử lý?","back":"Capital budget phân bổ tiền; risk budget phân bổ một đơn vị rủi ro như VaR, expected shortfall, tracking error hoặc risk contribution. Hai chiến lược dùng cùng số tiền có thể tiêu thụ risk budget khác nhiều."},{"id":"C05-03","los_ids":["CFA26-09-06-LOS05"],"front":"Marginal và component risk — giải thích và cách xử lý?","back":"Risk contribution nên đo tác động của vị thế tới portfolio total risk, không chỉ stand-alone σ. Portfolio concentration và correlations có thể khiến việc cộng các individual risks không bằng overall risk."},{"id":"C06-01","los_ids":["CFA26-09-06-LOS06"],"front":"Financial risks — giải thích và cách xử lý?","back":"Market risk gồm equity, interest rate, FX, commodity price; credit risk gồm counterparty default, migration và spread changes; liquidity risk gồm market liquidity và funding liquidity. Các exposure tương tác khi giá tài sản giảm và margin requirements tăng."},{"id":"C06-02","los_ids":["CFA26-09-06-LOS06"],"front":"Non-financial risks — giải thích và cách xử lý?","back":"Operational errors, cyberattacks, fraud, model risk, legal/regulatory, reputational, environmental, geopolitical và strategic risks. Chúng có thể tác động tài chính lớn, không nên coi rủi ro phi tài chính là không thể lượng hóa hoặc không quan trọng."},{"id":"C06-03","los_ids":["CFA26-09-06-LOS06"],"front":"Interaction qua chuỗi nguyên nhân — giải thích và cách xử lý?","back":"Cyber breach làm hoạt động dừng, khách hàng rút tiền, funding liquidity thắt chặt, credit rating xấu và interest costs tăng. Cú sốc tỷ giá có thể làm khách vay ngoại tệ khó trả nợ, gây credit loss."},{"id":"C07-01","los_ids":["CFA26-09-06-LOS07"],"front":"Risk measurement: sensitivity, volatility, VaR, ES — giải thích và cách xử lý?","back":"Sensitivity measures gồm duration, beta, delta, DV01; volatility mô tả biến động; VaR ước tính loss threshold ở confidence/horizon nhất định; Expected Shortfall đo kỳ vọng tổn thất trong tail vượt VaR. Không coi VaR là maximum possible loss."},{"id":"C07-02","los_ids":["CFA26-09-06-LOS07"],"front":"VaR models và assumptions — giải thích và cách xử lý?","back":"Parametric VaR giả định distribution, historical VaR dựa phân phối lịch sử, Monte Carlo mô phỏng scenarios theo model. Những phương pháp có model risk, sensitivity to sample, liquidity horizon và tail risk; cần backtesting/stress testing."},{"id":"C07-03","los_ids":["CFA26-09-06-LOS07"],"front":"Stress testing và scenario analysis — giải thích và cách xử lý?","back":"Stress test kiểm tra losses dưới cú sốc extreme nhưng hợp lý; scenario analysis kết hợp yield/FX/equity/credit events. Các thước đo này bổ sung chứ không thay thế VaR/ES. Stress phải xét correlated adverse moves và loss of liquidity."}],"review_status":"targeted_los_source_math_and_browser_QA_pass_not_exhaustive_all_PDFs"}]);
window.CFA_AUDIT_TOTALS=(function(previous){previous=previous||{};return {...previous,drafted:Math.max(Number(previous.drafted)||0,344),independently_reaudited:Math.max(Number(previous.independently_reaudited)||0,201),scope:"Targeted 3-source review, not exhaustive all uploaded PDFs"};})(window.CFA_AUDIT_TOTALS);
